1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	// An item surcharge hits every item the predicate accepts, charging its rate
89	// against that item's own base premium.
90	interface ItemSurcharge {
91	  appliesTo: (item: Item) => boolean;
92	  rate: number;
93	}
94	
95	const ITEM_SURCHARGES: ItemSurcharge[] = [
96	  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
97	  {
98	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
99	    rate: 0.3,
100	  },
101	];
102	
103	// One surcharge, totalled across every item it accepts.
104	const surchargeAcrossItems = (
105	  items: Item[],
106	  { appliesTo, rate }: ItemSurcharge,
107	): number =>
108	  items
109	    .filter(appliesTo)
110	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
111	
112	// Item-specific surcharges apply to the affected item's own base premium.
113	const itemSurchargesOf = (items: Item[]): number =>
114	  ITEM_SURCHARGES.reduce(
115	    (sum, surcharge) => sum + surchargeAcrossItems(items, surcharge),
116	    0,
117	  );
118	
119	const LOYALTY_DISCOUNT_RATE = -0.2;
120	
121	const LOYALTY_YEARS_THRESHOLD = 2;
122	
123	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
124	
125	// The context a policy-wide modifier is judged against: who the customer is,
126	// and how many quotes they have already been given in this scenario.
127	interface PolicyContext {
128	  customer: Customer;
129	  precedingQuotes: number;
130	}
131	
132	// A policy modifier hits the whole policy when the predicate accepts it,
133	// charging its rate against the policy base premium. Discounts are negative
134	// rates, so surcharges and discounts sum uniformly.
135	interface PolicyModifier {
136	  appliesTo: (context: PolicyContext) => boolean;
137	  rate: number;
138	}
139	
140	const POLICY_MODIFIERS: PolicyModifier[] = [
141	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
142	  {
143	    appliesTo: ({ customer }) =>
144	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
145	    rate: LOYALTY_DISCOUNT_RATE,
146	  },
147	  {
148	    appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
149	    rate: FOLLOW_UP_DISCOUNT_RATE,
150	  },
151	];
152	
153	// Policy-wide modifiers apply to the policy base premium, so they are computed
154	// from the base alone — item-specific modifiers are not part of their base.
155	const policyModifiersOf = (policyBase: number, context: PolicyContext): number =>
156	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
157	    (sum, { rate }) => sum + policyBase * rate,
158	    0,
159	  );
160	
161	const isInsurable = (item: Item): boolean => item.type in BASE_PREMIUMS;
162	
163	// MHPCO only writes policies over item types it has a price for, so an
164	// unpriceable item is rejected before any of it is quoted.
165	const rejectUninsurableItems = (items: Item[]): void => {
166	  const uninsurableItem = items.find((item) => !isInsurable(item));
167	
168	  if (uninsurableItem)
169	    throw new Error(`unknown item type: ${uninsurableItem.type}`);
170	};
171	
172	const quote = ({ items }: QuoteStep, context: PolicyContext): QuoteResult => {
173	  rejectUninsurableItems(items);
174	
175	  const policyBase = policyBasePremiumOf(items);
176	
177	  const premiumBeforeRounding =
178	    policyBase +
179	    itemSurchargesOf(items) +
180	    policyModifiersOf(policyBase, context) +
181	    PROCESSING_FEE;
182	
183	  return { premium: Math.ceil(premiumBeforeRounding) };
184	};
185	
186	const INSURANCE_VALUES: Record<string, number> = {
187	  sword: 1000,
188	  amulet: 600,
189	  staff: 800,
190	  potion: 400,
191	  rune: 250,
192	  moonstone: 250,
193	};
194	
195	const DEDUCTIBLE = 100;
196	
197	const CAP_MULTIPLE = 2;
198	
199	// A policy created by a quote step: what it covers, and how much of its
200	// payout cap is still available.
201	interface Policy {
202	  items: Item[];
203	  remainingCap: number;
204	}
205	
206	const policyFor = (items: Item[]): Policy => {
207	  const insuranceSum = items.reduce(
208	    (sum, item) => sum + INSURANCE_VALUES[item.type],
209	    0,
210	  );
211	
212	  return { items, remainingCap: CAP_MULTIPLE * insuranceSum };
213	};
214	
215	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
216	
217	const HALF_REIMBURSEMENT_RATE = 0.5;
218	
219	const FULL_REIMBURSEMENT_RATE = 1;
220	
221	// Damage to a highly enchanted item is reimbursed at half, before the
222	// deductible is taken off.
223	const reimbursementRateFor = (item: Item): number =>
224	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
225	    ? HALF_REIMBURSEMENT_RATE
226	    : FULL_REIMBURSEMENT_RATE;
227	
228	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
229	  damage.amount * reimbursementRateFor(damagedItem) - DEDUCTIBLE;
230	
231	// Settling a claim both reports a result and draws down the policy's cap.
232	interface Settlement {
233	  result: ClaimResult;
234	  updatedPolicy: Policy;
235	}
236	
237	// A damage matched to the insured item it settles against.
238	interface MatchedDamage {
239	  damage: Damage;
240	  damagedItem: Item;
241	}
242	
243	// A claim only pays against items the policy actually covers, so a damage with
244	// no still-available item of its type is rejected before any of it is settled.
245	// Removes the matched item from `available`, so it cannot be matched twice.
246	const takeInsuredItemFor = (damage: Damage, available: Item[]): Item => {
247	  const index = available.findIndex((item) => item.type === damage.itemType);
248	
249	  if (index < 0)
250	    throw new Error(`damaged item is not insured: ${damage.itemType}`);
251	
252	  return available.splice(index, 1)[0];
253	};
254	
255	// Each damage settles against a distinct insured item, so a policy covering
256	// two swords can absorb two sword damages — one per insured sword. Matching an
257	// item consumes it, leaving it unavailable to later damages.
258	const matchDamagesToItems = (
259	  damages: Damage[],
260	  items: Item[],
261	): MatchedDamage[] => {
262	  const available = [...items];
263	
264	  return damages.map((damage) => ({
265	    damage,
266	    damagedItem: takeInsuredItemFor(damage, available),
267	  }));
268	};
269	
270	// MHPCO does not entertain damage reports it would have to pay backwards.
271	const rejectNegativeDamages = (damages: Damage[]): void => {
272	  const negative = damages.find((damage) => damage.amount < 0);
273	
274	  if (negative) throw new Error(`damage amount is negative: ${negative.amount}`);
275	};
276	
277	const claim = ({ incident }: ClaimStep, policy: Policy): Settlement => {
278	  rejectNegativeDamages(incident.damages);
279	
280	  const desiredPayout = matchDamagesToItems(
281	    incident.damages,
282	    policy.items,
283	  ).reduce(
284	    (sum, { damage, damagedItem }) => sum + payoutForDamage(damage, damagedItem),
285	    0,
286	  );
287	
288	  // The total payout per policy is capped, so a claim pays at most what the
289	  // policy has left.
290	  // Rounded down in the MHPCO's favour before the cap is touched, so the cap
291	  // is drawn down by the whole G actually paid out.
292	  const payout = Math.floor(Math.min(desiredPayout, policy.remainingCap));
293	
294	  const remainingCap = policy.remainingCap - payout;
295	
296	  return {
297	    result: { payout, remainingCap },
298	    updatedPolicy: { ...policy, remainingCap },
299	  };
300	};
301	
302	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
303	  const results: StepResult[] = [];
304	
305	  const policies = new Map<number, Policy>();
306	
307	  let precedingQuotes = 0;
308	
309	  steps.forEach((step, index) => {
310	    if (step.op === "quote") {
311	      results.push(quote(step, { customer, precedingQuotes }));
312	      policies.set(index, policyFor(step.items));
313	      precedingQuotes += 1;
314	
315	      return;
316	    }
317	
318	    const { result, updatedPolicy } = claim(step, policies.get(step.policy)!);
319	
320	    results.push(result);
321	    policies.set(step.policy, updatedPolicy);
322	  });
323	
324	  return { results };
325	};
